ta['registros']):?><tr><td colspan="5"><div class="canaco-empty"><span class="canaco-empty-icon"><i class="ki-filled ki-discount"></i></span><strong>No hay promociones</strong><p>Registra la primera promoción comercial.</p></div></td></tr><?php endif;?></tbody></table></div><div class="kt-card-footer py-4"><span class="text-sm text-muted-foreground"><?= (int)$lista['total'] ?> resultado<?= (int)$lista['total']===1?'':'s' ?></span></div></div>
